import{_ as r,h as l,i as t,c as A,v as o,p as s,x as e,m as n,e as E,S as p}from"./chunks/framework.Dvtg8yj2.js";const c=JSON.parse('{"title":"QLoRA 作为压缩微调","description":"","frontmatter":{"title":"QLoRA 作为压缩微调","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/qlora-as-compression.md","filePath":"llm/qlora-as-compression.md","lastUpdated":1788454257000}'),d={name:"llm/qlora-as-compression.md"};function b(h,a,m,Q,B,L){const i=l("Mermaid");return t(),A("div",null,[a[1]||(a[1]=o('<h1 id="qlora-作为压缩微调" tabindex="-1">QLoRA 作为压缩微调 <a class="header-anchor" href="#qlora-作为压缩微调" aria-label="Permalink to &quot;QLoRA 作为压缩微调&quot;">​</a></h1><div class="epigraph"><p>压缩的对象是微调作业本身：基座以 4-bit 只读驻留，可学习增量仍是低秩；交付物是一份小适配器，而不是又一份全参 16-bit 副本。</p><footer>—— Dettmers 等，QLoRA: Efficient Finetuning of Quantized LLMs，NeurIPS 2023</footer></div><p><a href="/llm/qlora">QLoRA</a> 专文写 NF4、双重量化与分页优化器——那是<strong>怎么把 65B 塞进 48GB 去训</strong>。<a href="/llm/lora">LoRA</a> 专文写低秩增量的数学。本篇换一个问题：把 QLoRA 看成压缩策略时，它压缩的是哪一张账单，交付物如何进服务栈，以及它和 GPTQ 式推理压缩、全参 SFT 各差在哪。Dettmers 等人已经表明，在合适数据上，4-bit 基座加 16-bit 适配器可以贴近 16-bit LoRA；工程上这意味着微调可以从「复制一套大权重」改成「只生产一套小增量」。这是压缩，对象是<strong>训练与存储的工作副本</strong>，不是把基座的推理误差再优化一档。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一次全参微调的账单有三块：存一份可写的 16-bit（或更高）权重；为它们准备优化器状态（Adam 大约再乘 2–3）；存激活以便反向。LoRA 砍掉大部分可写参数与对应优化器，但只读基座仍按 16-bit 常驻，65B 级单卡仍不够。若微调的目标只是领域适配，最终上线往往还是「基座 + 适配器」或「合并后再量化」，中间那份全参 16-bit 副本既贵又多余。</p><p>朴素想法「先 GPTQ 再在整数上反向」会失败：整数权重没有 STE 之外的合法梯度，适配器也看不见稳定的连续 \\(W_0\\)。QLoRA 的压缩命题是：把只读基座的<strong>存储</strong>压到 4-bit，把计算留在 16-bit，把可写部分留在 LoRA 的低秩里。压缩比出现在磁盘、训练显存、以及多租户时每份任务检查点的体积，而不是出现在 decode 的 4-bit 核里——后者要另做推理量化。</p><h3 id="三份「4-bit」不要并成一种压缩" tabindex="-1">三份「4-bit」不要并成一种压缩 <a class="header-anchor" href="#三份「4-bit」不要并成一种压缩" aria-label="Permalink to &quot;三份「4-bit」不要并成一种压缩&quot;">​</a></h3><p>推理 W4A16 的 4-bit（GPTQ/AWQ）最小化校准集上的层输出误差，权重不再更新。QLoRA 的 4-bit 最小化的是显存，网格是 NF4 分位数，前向必须反量化。QAT 的 4-bit 是假量化仿真，主权重仍浮点。把 QLoRA 训完的适配器接到 GPTQ 基座上而不对拍反量化，属于格式错误，不是压缩级联。压缩微调的交付清单必须写清：基座用哪套 4-bit、适配器精度、合并发生在反量化之前还是之后。</p><p><span class="marginnote">Guanaco 一类结果说明的是「在该数据与超参下，QLoRA 可接近 16-bit LoRA」，不是「任何任务上 4-bit 基座等于全参」。压缩微调省的是作业规模；任务是否低秩可适配，仍由数据与秩决定，QLoRA 不增加 LoRA 容量。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>作业配方：加载冻结的 NF4 基座；在注意力与 MLP 的线性层上插 \\(A,B\\)；前向反量化 \\(W_0\\) 到 16-bit，加 \\((\\alpha/r)BA\\)；反向只更新适配器与（可选）层归一化；优化器用分页以消化检查点尖峰。数据与学习率按 LoRA 选，不按全参 SFT 选。训练结束存适配器（通常几十到几百 MB 级，视秩与层数），基座检查点共享、只读。</p><p>部署有三条压缩路径。其一：推理仍走 QLoRA 图，4-bit 基座加 16-bit 适配器，多租户只换 \\(A,B\\)，见多 LoRA 服务。其二：合并 \\(\\tilde W=W_0^{\\mathrm{dequant}}+\\Delta W\\)，再做 GPTQ/AWQ，得到单份 W4A16，适配器消失，换任务要重新合并量化。其三：合并后保持 16-bit，放弃推理压缩。QLoRA 作为压缩微调，默认指向前两条里的第一条：微调产出物保持小增量，基座一份共享。</p>',12)),(t(),s(p,null,{default:e(()=>[E(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20BASE%5B%22%E5%85%B1%E4%BA%AB%204-bit%20%E5%9F%BA%E5%BA%A7%22%5D%20--%3E%20DQ%5B%22%E5%8F%8D%E9%87%8F%E5%8C%96%E5%88%B0%2016-bit%22%5D%0A%20%20DQ%20--%3E%20ADD%5B%22%E5%8A%A0%E4%B8%8A%E4%BB%BB%E5%8A%A1%20LoRA%22%5D%0A%20%20AD%5B%22%E5%B0%8F%E9%80%82%E9%85%8D%E5%99%A8%E6%A3%80%E6%9F%A5%E7%82%B9%22%5D%20--%3E%20ADD%0A%20%20ADD%20--%3E%20Y%5B%22%E4%BB%BB%E5%8A%A1%E5%89%8D%E5%90%91%22%5D%0A%20%20Y%20--%3E%20MERGE%7B%22%E4%B8%8A%E7%BA%BF%E7%AD%96%E7%95%A5%22%7D%0A%20%20MERGE%20--%3E%7C%E5%A4%9A%E7%A7%9F%E6%88%B7%7C%20KEEP%5B%22%E4%BF%9D%E6%8C%81%E5%88%86%E7%A6%BB%22%5D%0A%20%20MERGE%20--%3E%7C%E5%8D%95%E6%A8%A1%E5%9E%8B%E5%90%9E%E5%90%90%22%7C%20GPTQ%5B%22%E5%90%88%E5%B9%B6%E5%90%8E%E5%86%8D%20PTQ%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>与全参 SFT 比：可写参数从 \\(O(d^2)\\) 降到 \\(O(rd)\\)，优化器状态同比例降，基座存储再除以约 4。与普通 LoRA 比：可写部分相同，只读基座再压 4 倍。压缩比是乘法的，不是另发明一种低秩。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>量化误差 \\(E\\) 固定在冻结的 \\(\\tilde W_0=W_0+E\\) 上。适配器在 16-bit 里拟合任务时，可以吸收 \\(E\\) 在任务子空间上的投影，相当于用低秩去补一块静态扰动。这是压缩微调仍然准的原因：噪声不进入优化器的二阶动量乱抖，也不对 \\(W_0\\) 做 STE。吸收不了的分量成为拟合上限，表现为「再加数据也不贴 16-bit LoRA」，应提高秩或退回 16-bit 基座，而不是把学习率拉大。</p><p>多任务时，压缩发生在<strong>检查点扇出</strong>。\\(N\\) 个领域若全参微调，是 \\(N\\) 份大权重；QLoRA 是 1 份 4-bit 基座加 \\(N\\) 份小适配器。这与剪枝、蒸馏那种「一个更小的稠密网」不同：基座并未变小到可以丢掉，只是被共享。若每个任务都合并回大权重再分发，扇出压缩立刻消失。</p><p><span class="marginnote">把 QLoRA 当成「免费的模型压缩包」发给端侧，端侧仍要能反量化 NF4 并加 LoRA。没有对应核时，必须合并并改成目标引擎的 4-bit 格式，那是另一次 PTQ，可能掉点。压缩微调的产物不等于压缩推理的产物。</span></p><h3 id="何时它不是好的压缩" tabindex="-1">何时它不是好的压缩 <a class="header-anchor" href="#何时它不是好的压缩" aria-label="Permalink to &quot;何时它不是好的压缩&quot;">​</a></h3><p>需要改表示几何的任务——大改词表、解冻嵌入与 lm_head、长程继续预训练——低秩加冻结基座装不下，压缩比是假的，因为你很快会解冻更多参数，优化器回来，QLoRA 退化为「略省存储的全参」。安全对齐若依赖全层小更新，LoRA 秩不够会表现为拒答不稳；那是容量问题，换 4-bit 存储救不了。此时压缩应改走蒸馏小模型或全参再 PTQ，而不是加深 QLoRA。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>NF4 假设权重近似正态；已经不规则量化或稀疏的基座不适合当 QLoRA 起点。分页优化器绑定统一内存，换 NPU 可能没有。训练与评估必须同一反量化表。合并后再 GPTQ，校准应使用合并后的权重，不要用合并前的浮点老师去校准已经加了 \\(\\Delta W\\) 的层——对象变了。</p><p>成本会计：单卡能训不等于应该训 65B。若产品最终要 W4A16 单模型，可能直接在 16-bit LoRA 或全参上微调再 GPTQ 更少一次数值跳跃。QLoRA 的压缩价值在「必须单卡 / 必须多适配器并存 / 不能持有全参写权限」这些约束成立时最大。</p><h3 id="与推理-ptq-的衔接清单" tabindex="-1">与推理 PTQ 的衔接清单 <a class="header-anchor" href="#与推理-ptq-的衔接清单" aria-label="Permalink to &quot;与推理 PTQ 的衔接清单&quot;">​</a></h3><p>导出前确认：基座是 NF4 还是已转 INT4；适配器是否已合并；目标服务引擎的 group_size 与对称约定；验证集上相对 16-bit LoRA 的生成差，而不是只看训练 loss。缺任一项，压缩微调会在上线当周变成事故，看起来像量化论文不可复现。</p><p><span class="marginnote">Dettmers 文中的双重量化压的是尺度元数据，对适配器体积几乎无感。宣传「QLoRA 把模型压到 4-bit」若省略「基座冻结、增量仍 16-bit」，会让人以为交付的是 GPTQ 文件。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>作为压缩微调，QLoRA 压缩的是训练副本与多任务扇出：共享 4-bit 只读基座，交付小适配器。</li><li>计算仍在 16-bit，低秩增量可吸收量化误差在任务方向上的投影；不增加 LoRA 容量。</li><li>三种 4-bit（推理 PTQ、QLoRA 存储、QAT 假量化）网格与梯度约定不同，不能对拍加载。</li><li>上线可保持分离以维持扇出压缩，或合并后再 PTQ 以换单模型吞吐。</li><li>需解冻大量参数的任务会吃掉压缩比；应改方法而不是加大学习率。</li><li>端侧若无 NF4+LoRA 核，必须再做一次目标格式的量化。</li><li>出处：Dettmers 等，<em>QLoRA: Efficient Finetuning of Quantized LLMs</em>，NeurIPS 2023。对照 Frantar et al., GPTQ；Jacob et al., QAT, CVPR 2018。</li></ul>',15))])}const T=r(d,[["render",b]]);export{c as __pageData,T as default};
